'use strict';
const $=s=>document.querySelector(s), app=$('#app'), KEY='jk-missao-v1';
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let sound=false, selected=null, state=null, storageOK=true;
try{state=JSON.parse(sessionStorage.getItem(KEY)||'null')}catch(e){storageOK=false}
function fresh(){return {version:1,phase:'intro',introStart:Date.now(),mode:'duo',grade:'6º ano',names:['',''],group:'',team:'',index:0,answers:[],records:TASKS.map(()=>({errors:0,hint:false,solved:false,points:0})),warnings:[],start:null,end:null,reason:''}}
if(!state||state.version!==1||!Array.isArray(state.records)||state.records.length!==15)state=fresh();
// Mantém sessões anteriores em dupla e identifica sua série sem apagar progresso.
state.mode=state.mode==='solo'?'solo':'duo';
state.grade=state.grade||((state.group||'').match(/^[0-9]+º/)?.[0] ? (state.group.match(/^[0-9]+º/)[0]+' ano') : '6º ano');
function solo(){return state.mode==='solo'}
function participants(){return state.names.filter(Boolean).join(' + ')}
function classLabel(){return state.grade+' · '+state.group}
function participation(t){if(solo())return '<p class="tag">Modo individual · resolva todos os desafios no seu ritmo.</p>';return '<div class="cooperation">'+(t.role===2?'<b>Confirmem após conversar:</b><label><input id="agree1" type="checkbox">'+esc(state.names[0])+' concorda</label><label><input id="agree2" type="checkbox">'+esc(state.names[1])+' concorda</label>':'<label><input id="agree1" type="checkbox">'+esc(state.names[t.role])+' conduziu; o colega ajudou.</label>')+'</div>'}
function save(){try{sessionStorage.setItem(KEY,JSON.stringify(state))}catch(e){storageOK=false}}
function beep(){if(!sound)return;try{const A=window.AudioContext||window.webkitAudioContext,a=new A(),o=a.createOscillator(),g=a.createGain();o.connect(g);g.connect(a.destination);g.gain.value=.025;o.frequency.value=660;o.start();o.stop(a.currentTime+.12);o.onended=()=>a.close()}catch(e){}}
$('#sound').onclick=()=>{sound=!sound;$('#sound').textContent='Som: '+(sound?'ligado':'desligado');if(sound)beep()};
function time(n){n=Math.max(0,Math.ceil(n));return String(Math.floor(n/60)).padStart(2,'0')+':'+String(n%60).padStart(2,'0')}
function score(){return state.records.reduce((s,r)=>s+r.points,0)}
function left(){return Math.max(0,1680-(Date.now()-state.start)/1000)}
function check(t,a){if(t.type==='code')return String(a).trim()===t.answer;if(t.type==='choice')return a===t.answer;if(t.type==='multi')return Array.isArray(a)&&a.length===t.answer.length&&[...a].sort().every((v,i)=>v===[...t.answer].sort()[i]);return Array.isArray(a)&&a.length===t.answer.length&&a.every((v,i)=>v===t.answer[i])}
function initAnswer(){const t=TASKS[state.index];if(state.answers[state.index]===undefined)state.answers[state.index]=t.type==='order'?t.items.map((_,i)=>i):t.type==='multi'?[]:['sort','match'].includes(t.type)?t.items.map(()=>null):t.type==='code'?'':null}

const OPENING_ART="data:image/jpeg;base64,";
function missionArt(n){const drawings=[
'<rect x="18" y="18" width="84" height="58" rx="7"/><path d="M60 76v13M36 90h48M30 32h60M30 43h32"/>',
'<rect x="18" y="16" width="84" height="76" rx="8"/><path d="M18 37h84M30 27h2m10 0h2m10 0h2M42 52 30 63l12 11m36-22 12 11-12 11M66 49 54 79"/>',
'<path d="M60 12 97 27v27c0 27-37 44-37 44S23 81 23 54V27Z"/><rect x="43" y="46" width="34" height="27" rx="5"/><path d="M49 46v-8a11 11 0 0 1 22 0v8M60 57v6"/>',
'<path d="M16 35v-10a7 7 0 0 1 7-7h27l13 14h34a7 7 0 0 1 7 7v49H16Z"/><path d="M16 46h88M35 62h22m-22 13h48"/>',
'<rect x="19" y="30" width="82" height="63" rx="8"/><path d="M42 30v-9a18 18 0 0 1 36 0v9M32 47h56M34 62h2m13 0h2m13 0h2m13 0h2M34 77h2m13 0h2m13 0h2m13 0h2"/>'
];return '<svg class="mission-art" viewBox="0 0 120 110" aria-hidden="true" fill="none" stroke="currentColor" stroke-width="4" stroke-linecap="round" stroke-linejoin="round">'+drawings[n]+'</svg>'}
const artStyle=document.createElement('style');
artStyle.textContent='.opening-art{display:block;width:100%;height:auto;border-radius:16px;border:1px solid #536486;margin:20px 0 8px}.art-caption{font-size:13px;color:#bac6e5;margin:0 0 20px}.mission-art{display:block;width:112px;height:104px;color:#81f2cd;margin:0 auto 12px;padding:8px;background:radial-gradient(ellipse,#4a3875,transparent 72%);filter:drop-shadow(0 4px 12px #0b1227)}@media print{.opening-art,.mission-art,.art-caption{display:none}}';
document.head.appendChild(artStyle);

function intro(){app.innerHTML=`<div class="grid"><section><div class="intro-author"><strong>Professor Welington Laignier</strong><span>EMEF Juscelino Kubitschek · Escola JK</span></div><span class="eyebrow">OPERAÇÃO ESCOLA CONECTADA</span><h1>O mistério começa<br>com você.</h1><img class="opening-art" src="${OPENING_ART}" alt="Lia, a assistente digital, em um laboratório ilustrado com computadores, quadro de pistas, pastas e um escudo de segurança." width="1672" height="941"><p class="art-caption">Conheça Lia, sua guia na investigação digital da Escola JK.</p><p>Arquivos perdidos, uma estação com falhas e uma mensagem suspeita. Investigue sozinho ou forme uma dupla para recuperar o laboratório.</p><div class="card"><b>Conteúdo de referência: 6º ano · BNCC Computação</b><p>Atividade preparada para o 6º ano, com referência aos eixos Pensamento Computacional, Mundo Digital e Cultura Digital. Outras séries podem participar em caráter de teste; o conteúdo permanece o mesmo.</p></div><div class="stats"><span class="tag">5 missões</span><span class="tag">15 desafios</span><span class="tag">Até 100 pontos</span></div><p>Individual: você assume todos os desafios. Em dupla: alternem o mouse, conversem e confirmem juntos. Não há ranking.</p><div class="card"><b>30 minutos de atividade</b><p>2 min para identificação + até 28 min para as missões e o resultado. É possível terminar antes. Reserve os últimos 2 min para conversar sobre o resultado.</p></div></section><section class="panel"><span class="eyebrow">IDENTIFICAÇÃO</span><p>Identificação · <b id="introClock">02:00</b></p><form id="startForm"><label for="mode">Como deseja jogar?</label><select id="mode"><option value="solo" ${solo()?'selected':''}>Sozinho · individual</option><option value="duo" ${!solo()?'selected':''}>Em dupla · cooperativo</option></select><label for="p1">${solo()?'Seu nome completo':'Jogador 1 · nome completo'}</label><input id="p1" maxlength="100" required autocomplete="off" value="${esc(state.names[0])}">${!solo()?`<label for="p2">Jogador 2 · nome completo</label><input id="p2" maxlength="100" required autocomplete="off" value="${esc(state.names[1])}">`:''}<label for="grade">Série / ano</label><input id="grade" list="grades" maxlength="40" required value="${esc(state.grade)}" placeholder="Ex.: 7º ano"><datalist id="grades">${Array.from({length:9},(_,i)=>'<option value="'+(i+1)+'º ano">').join('')}<option value="1ª série do Ensino Médio"><option value="2ª série do Ensino Médio"><option value="3ª série do Ensino Médio"><option value="EJA"></datalist><label for="group">Turma</label><input id="group" maxlength="60" required value="${esc(state.group)}" placeholder="Ex.: A, B ou 7º C"><label for="team">Nome da equipe / agente · opcional</label><input id="team" maxlength="60" value="${esc(state.team)}"><p id="formError" class="warning" role="alert"></p><button type="submit">Iniciar investigação →</button></form><small>Os dados ficam nesta aba. Ao finalizar, baixe o CSV e entregue ao professor. Nenhum resultado é enviado automaticamente.</small></section></div>`;
 const update=()=>{state.names=[$('#p1').value,solo()?'':$('#p2').value];state.grade=$('#grade').value;state.group=$('#group').value;state.team=$('#team').value;save()};
 $('#startForm').oninput=update;$('#startForm').onchange=update;
 $('#mode').onchange=()=>{update();state.mode=$('#mode').value;save();render()};
 $('#startForm').onsubmit=e=>{e.preventDefault();update();state.names=state.names.map(n=>n.trim());state.grade=state.grade.trim();state.group=state.group.trim();const names=solo()?[state.names[0]]:state.names;if(names.some(n=>n.split(/\s+/).length<2)||(!solo()&&names[0].toLocaleLowerCase()===names[1].toLocaleLowerCase())){$('#formError').textContent=solo()?'Informe seu nome completo.':'Informem o nome completo de dois participantes diferentes.';return}if(!state.grade||!state.group){$('#formError').textContent='Informe a série / ano e a turma.';return}state.phase='play';state.start=Date.now();save();render()};}
function taskUI(t,a){if(t.type==='sort')return `<p class="hint">Clique em um item colocado para devolvê-lo à bancada.</p><div class="tokens" id="bank">${t.items.map((x,i)=>a[i]===null?`<button class="token ${selected===i?'selected':''}" type="button" draggable="true" data-item="${i}">${esc(x)}</button>`:'').join('')}</div>${t.groups.map((g,k)=>`<div class="drop" tabindex="0" role="button" aria-label="Colocar item em ${esc(g)}" data-group="${k}"><b>${esc(g)}</b><div>${t.items.map((x,i)=>a[i]===k?`<button class="token" data-return="${i}">${esc(x)} ×</button>`:'').join('')}</div></div>`).join('')}`;
 if(t.type==='match')return `<div class="rows">${t.items.map((x,i)=>`<div class="card"><label for="match${i}">${esc(x)}</label><select id="match${i}" data-match="${i}"><option value="">Selecione a função</option>${t.options.map((v,j)=>`<option value="${j}" ${a[i]===j?'selected':''}>${esc(v)}</option>`).join('')}</select></div>`).join('')}</div>`;
 if(t.type==='order')return `<ol class="sequence">${a.map((v,i)=>`<li><b>${i+1}.</b><span>${esc(t.items[v])}</span><button class="quiet" data-move="${i},-1" aria-label="Subir ${esc(t.items[v])}" ${i===0?'disabled':''}>↑</button><button class="quiet" data-move="${i},1" aria-label="Descer ${esc(t.items[v])}" ${i===a.length-1?'disabled':''}>↓</button></li>`).join('')}</ol>`;
 if(t.type==='code')return `<label for="code">Código de quatro algarismos</label><input id="code" inputmode="numeric" pattern="[0-9]{4}" maxlength="4" autocomplete="off" value="${esc(a)}">`;
 return `<div class="choices">${t.options.map((v,i)=>`<label class="choice"><input type="${t.type==='multi'?'checkbox':'radio'}" name="answer" value="${i}" ${t.type==='multi'?a.includes(i)?'checked':'':a===i?'checked':''}>${esc(v)}</label>`).join('')}</div>`;
}
function renderPlay(){initAnswer();const i=state.index,t=TASKS[i],r=state.records[i],m=MISSIONS[t.mission],a=state.answers[i],role=solo()?`Vez de ${state.names[0]} · individual`:t.role===2?'Decisão conjunta':`Vez de ${state.names[t.role]}`;
app.innerHTML=`<div class="stats"><div><span class="eyebrow">${esc(state.team||'AGENTES DIGITAIS')} · ${esc(classLabel())}</span><div>${esc(participants())}</div></div><span class="stat" id="clock">${time(left())}</span><span class="stat">${score()} / 100</span></div><div class="bar" aria-label="Progresso"><span style="width:${state.records.filter(x=>x.solved).length/15*100}%"></span></div><div id="notice" role="status"></div><nav class="map" aria-label="Mapa das missões">${MISSIONS.map((x,j)=>`<span class="node ${j===t.mission?'active':''} ${state.records.slice(j*3,j*3+3).every(r=>r.solved)?'done':''}">${j+1}. ${esc(x.name)}</span>`).join('')}</nav><div class="grid"><section class="panel"><span class="eyebrow">MISSÃO ${t.mission+1} · DESAFIO ${i%3+1}/3 · ${t.points} PONTOS</span><h2>${esc(t.title)}</h2><span class="tag">${esc(role)}</span><p>${esc(t.prompt)}</p><div id="task">${taskUI(t,a)}</div><div id="feedback" role="status">${r.solved?`<div class="feedback">Correto! ${esc(t.explain)}<br><b>+${r.points} pontos</b></div>`:''}</div>${r.hint?`<p class="hint">Dica: ${esc(t.hint)}</p>`:''}${!r.solved?`${participation(t)}<button id="submit">Verificar solução</button><button id="hint" class="quiet" ${r.hint||state.records.filter(x=>x.hint).length>=5?'disabled':''}>${solo()?'Dica':'Dica da dupla'} (−1 ponto)</button><small> Até 5 dicas; 1 por desafio. Cada erro reduz 1 ponto deste desafio.</small>`:`${i%3===2&&t.mission<4?`<div class="clue">Pista recuperada: ${esc(m.clue)}</div>`:''}<button id="next">${i===14?'Ver resultado →':'Continuar →'}</button>`}</section><aside><div class="panel">${missionArt(t.mission)}<span class="eyebrow">${m.icon} CENTRAL DE INVESTIGAÇÃO</span><h3>${esc(m.name)}</h3><p>${esc(m.story)}</p><small>Meta da missão: ${t.mission===4?'6':'5'} min · sem espera obrigatória.</small></div><div class="panel"><h3>Caderno de pistas</h3>${MISSIONS.slice(0,4).map((x,j)=>state.records[j*3+2].solved?`<div class="clue">${esc(x.clue)}</div>`:`<p>🔒 Pista ${j+1}: concluam a missão ${j+1}.</p>`).join('')}</div><button id="finish" class="quiet">Encerrar e registrar progresso</button><div id="finishConfirm"></div></aside></div>`;
 if(r.solved){document.querySelectorAll('#task input,#task select,#task button').forEach(e=>e.disabled=true);$('#next').onclick=()=>{if(i===14)finish('concluída');else{state.index++;selected=null;save();render()}}}else{
 bindTask(t,a);$('#submit').onclick=submit;$('#hint').onclick=()=>{if(r.hint||state.records.filter(x=>x.hint).length>=5)return;r.hint=true;save();render()};}
 $('#finish').onclick=()=>{$('#finishConfirm').innerHTML='<p>Encerrar agora registra a missão como incompleta.</p><button id="yesFinish">Confirmar encerramento</button><button id="cancelFinish" class="quiet">Continuar jogando</button>';$('#yesFinish').onclick=()=>finish(solo()?'encerrada pelo participante':'encerrada pela dupla');$('#cancelFinish').onclick=()=>$('#finishConfirm').replaceChildren()};
}
function bindTask(t,a){
 const changed=()=>save();
 if(t.type==='sort'){
 document.querySelectorAll('[data-item]').forEach(b=>{b.onclick=()=>{selected=Number(b.dataset.item);render()};b.ondragstart=e=>{selected=Number(b.dataset.item);e.dataTransfer.setData('text/plain',String(selected))}});
 document.querySelectorAll('[data-group]').forEach(d=>{const put=()=>{if(selected===null)return;a[selected]=Number(d.dataset.group);selected=null;save();render()};d.onclick=e=>{if(!e.target.closest('[data-return]'))put()};d.onkeydown=e=>{if(e.target===d&&(e.key==='Enter'||e.key===' ')){e.preventDefault();put()}};d.ondragover=e=>e.preventDefault();d.ondrop=e=>{e.preventDefault();put()}});
 document.querySelectorAll('[data-return]').forEach(b=>b.onclick=e=>{e.stopPropagation();a[Number(b.dataset.return)]=null;save();render()});
 }else if(t.type==='match')document.querySelectorAll('[data-match]').forEach(s=>s.onchange=()=>{a[Number(s.dataset.match)]=s.value===''?null:Number(s.value);changed()});
 else if(t.type==='order')document.querySelectorAll('[data-move]').forEach(b=>b.onclick=()=>{const [k,d]=b.dataset.move.split(',').map(Number);[a[k],a[k+d]]=[a[k+d],a[k]];save();render()});
 else if(t.type==='code')$('#code').oninput=e=>{state.answers[state.index]=e.target.value;changed()};
 else document.querySelectorAll('[name=answer]').forEach(x=>x.onchange=()=>{state.answers[state.index]=t.type==='multi'?Array.from(document.querySelectorAll('[name=answer]:checked')).map(x=>Number(x.value)):Number(x.value);changed()});
}
function submit(){if(left()<=0){finish('tempo esgotado');return}const t=TASKS[state.index],r=state.records[state.index],a=state.answers[state.index];
 const say=(s,bad=true)=>{$('#feedback').innerHTML=`<div class="feedback ${bad?'bad':''}">${esc(s)}</div>`};
 if(!solo()&&(!$('#agree1').checked||(t.role===2&&!$('#agree2').checked))){say('Antes de verificar, confirmem a participação e a decisão da dupla.');return}
 if(a===null||a===''||(Array.isArray(a)&&(a.length===0||a.some(x=>x===null)))){say('Completem a solução antes de verificar.');return}
 if(check(t,a)){r.solved=true;r.points=Math.max(0,t.points-r.errors-(r.hint?1:0));save();beep();render()}else{r.errors++;save();say(r.errors>=3?'Vamos aprender com a solução: '+t.explain+' Ajustem a resposta e confirmem novamente.':'Ainda não. '+t.hint+' Conversem e tentem novamente. (−1 ponto deste desafio)')}
}
function finish(reason){state.phase='result';state.end=Date.now();state.reason=reason;save();render()}
function elapsed(){return Math.min(1680,Math.max(0,Math.round(((state.end||Date.now())-state.start)/1000)))}
function result(){const completed=state.records.every(r=>r.solved),solved=state.records.filter(r=>r.solved).length,errors=state.records.reduce((s,r)=>s+r.errors,0),hints=state.records.filter(r=>r.hint).length;
 app.innerHTML=`<section class="panel"><span class="eyebrow">RELATÓRIO DA OPERAÇÃO</span><h1>${completed?'Missão concluída!':'Investigação registrada'}</h1><p>${completed?'O laboratório da Escola JK foi recuperado!':'Parte das pistas foi recuperada. Converse sobre o que aprendeu com o professor.'}</p><h2>${esc(participants())}</h2><p>${esc(classLabel())} · ${solo()?'Individual':'Em dupla'} · Equipe / agente: ${esc(state.team||'Agentes digitais')}</p><div class="stats"><span class="stat">${score()} / 100 pontos</span><span>${solved}/15 desafios resolvidos</span><span>Tempo de jogo: ${time(elapsed())}</span></div><p>${errors} tentativas incorretas · ${hints} dicas · Situação: ${completed?'concluída':'incompleta'} (${esc(state.reason)})</p><table><thead><tr><th>Missão</th><th>Progresso</th><th>Pontos</th></tr></thead><tbody>${MISSIONS.map((m,j)=>{const rs=state.records.slice(j*3,j*3+3);return `<tr><td>${esc(m.name)}</td><td>${rs.filter(r=>r.solved).length}/3</td><td>${rs.reduce((s,r)=>s+r.points,0)}/20</td></tr>`}).join('')}</tbody></table><p class="no-print">Baixe o CSV e entregue ao professor. O resultado não é enviado pela internet.</p><button id="csv">Baixar resultado CSV</button><button id="print" class="quiet">Imprimir / salvar PDF</button><button id="new" class="quiet">Nova participação</button><div id="resetConfirm"></div></section>${completed?`<section class="panel" id="certificate"><span class="eyebrow">CERTIFICADO DIGITAL · ESCOLA JK</span><h2>Agentes digitais — Missão concluída</h2><p>Certificamos a participação de <b>${esc(state.names[0])}</b>${solo()?'':` e <b>${esc(state.names[1])}</b>`}, da turma ${esc(classLabel())}, na aventura educativa Missão Digital — O Mistério da Escola Conectada.</p><p>Hardware · Software · Segurança · Organização · Pensamento computacional</p><p>${esc(new Date(state.end).toLocaleDateString('pt-BR'))} · ${score()} pontos</p></section>`:''}<section class="panel"><h3>Conversa de encerramento · 2 min</h3><p>Qual pista foi mais desafiadora? O que fazer ao receber uma mensagem suspeita? Como a organização das pastas ajudou a resolver o mistério?</p></section>`;
 $('#csv').onclick=downloadCSV;$('#print').onclick=()=>window.print();$('#new').onclick=()=>{$('#resetConfirm').innerHTML='<p>Já exportou o CSV? O progresso desta participação será substituído.</p><button id="resetYes">Sim, iniciar nova participação</button>';$('#resetYes').onclick=()=>{state=fresh();save();render()}};
}
function csvText(){const safe=v=>{let s=String(v??'');if(/^[\s]*[=+@-]/.test(s))s="'"+s;return '"'+s.replace(/"/g,'""')+'"'};
 const rows=[['sessao','data','jogador_1','jogador_2','modo','serie_ano','turma','equipe','situacao','tempo_jogo_segundos','pontos_total','missao','desafio','resolvido','pontos_desafio','erros','dica']];
 state.records.forEach((r,i)=>rows.push([state.start,new Date(state.end).toISOString(),state.names[0],solo()?'':state.names[1],solo()?'individual':'dupla',state.grade,state.group,state.team,state.records.every(x=>x.solved)?'concluída':'incompleta',elapsed(),score(),Math.floor(i/3)+1,i+1,r.solved?'sim':'não',r.points,r.errors,r.hint?'sim':'não']));return '\ufeff'+rows.map(r=>r.map(safe).join(';')).join('\r\n')}
function downloadCSV(){const blob=new Blob([csvText()],{type:'text/csv;charset=utf-8;'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`missao-jk-${state.start}.csv`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
function render(){if(state.phase==='intro')intro();else if(state.phase==='result')result();else renderPlay();if(!storageOK)app.insertAdjacentHTML('afterbegin','<p class="warning">O navegador não permitiu salvar o progresso. Mantenham esta aba aberta e exportem o CSV ao terminar.</p>');save()}
function tick(){if(state.phase==='intro'){const c=$('#introClock');if(c){const rem=120-(Date.now()-state.introStart)/1000;c.textContent=rem>0?time(rem):'Tempo previsto encerrado — completem os nomes para iniciar';}return}if(state.phase!=='play')return;const rem=left();if(rem<=0){finish('tempo esgotado');return}if($('#clock'))$('#clock').textContent=time(rem);for(const n of [600,300,60])if(rem<=n&&!state.warnings.includes(n)){state.warnings.push(n);save();beep()}if($('#notice'))$('#notice').textContent=rem<=60?'Resta menos de 1 minuto. O progresso será registrado automaticamente.':rem<=300?'Restam menos de 5 minutos. Priorizem as pistas finais.':rem<=600?'Restam menos de 10 minutos. Confiram o progresso da dupla.':'';}
document.querySelector('.brand small').textContent='ESCOLA JK · CONTEÚDO DE REFERÊNCIA: 6º ANO';
render();tick();setInterval(tick,500);
